insert into public.sq_lorekeeper (term_id, is_active, grade_level, passage, question, choice_a, choice_b, choice_c, choice_d, correct_choice) values
  (1, true, 6, NULL, 'Scientists classify all living things into how many kingdoms?', 'Four', 'Five', 'Six', 'Eight', 'c'),
  (1, true, 6, NULL, 'Which kingdom includes single-celled organisms without a nucleus, like most bacteria?', 'Kingdom Bacteria (Eubacteria)', 'Kingdom Fungi', 'Kingdom Animalia', 'Kingdom Plantae', 'a'),
  (1, true, 6, NULL, 'Which kingdom includes organisms like mushrooms and molds that absorb nutrients from their surroundings?', 'Kingdom Protista', 'Kingdom Fungi', 'Kingdom Animalia', 'Kingdom Archaea', 'b'),
  (1, true, 6, NULL, 'Which kingdom is made up of mostly single-celled organisms that are more complex than bacteria, like amoebas?', 'Kingdom Protista', 'Kingdom Fungi', 'Kingdom Plantae', 'Kingdom Animalia', 'a'),
  (1, true, 6, NULL, 'Which of these correctly lists the taxonomic levels from broadest to most specific?', 'Species, genus, family, order, class, phylum, kingdom', 'Kingdom, phylum, class, order, family, genus, species', 'Kingdom, species, phylum, genus, class, order, family', 'Phylum, kingdom, class, order, genus, family, species', 'b'),
  (1, true, 6, NULL, 'In the taxonomic system, which level is more specific: family or genus?', 'Family', 'Genus', 'They are the same level', 'Neither is more specific', 'b'),
  (1, true, 6, NULL, 'A species'' full scientific name is made up of its', 'Kingdom and phylum', 'Genus and species names', 'Class and order', 'Family and kingdom', 'b'),
  (1, true, 6, NULL, 'Two organisms belonging to the same genus but different species are', 'Identical in every way', 'Closely related but distinct species', 'Always in different kingdoms', 'Never related at all', 'b'),
  (1, true, 6, NULL, 'Archaea are often found in extreme environments like hot springs. Which kingdom do they belong to?', 'Kingdom Archaea', 'Kingdom Fungi', 'Kingdom Animalia', 'Kingdom Plantae', 'a'),
  (1, true, 6, NULL, 'Why do scientists use a standardized classification system for organisms?', 'To organize and identify species consistently across the world, regardless of language', 'To make studying biology harder', 'Because every country uses different rules with no need for consistency', 'It has no real scientific purpose', 'a'),
  (1, true, 6, 'In a forest ecosystem, energy flows from producers to consumers. Trees and grasses use sunlight to make food. Deer eat the grasses. Wolves eat the deer. When any organism dies, decomposers break it down, releasing nutrients back into the soil.', 'In this ecosystem, what happens to energy as it moves from producers to top predators?', 'Energy increases at each level', 'Energy decreases at each level as it is used or lost as heat', 'Energy stays exactly the same at every level', 'Energy disappears completely at the first level', 'b'),
  (1, true, 6, NULL, 'A loss of habitat, such as deforestation, most directly threatens biodiversity by', 'Increasing the number of species instantly', 'Removing the homes and resources species need to survive', 'Having no effect on wildlife', 'Making ecosystems more stable', 'b'),
  (1, true, 6, NULL, 'An invasive species can threaten biodiversity because it often', 'Outcompetes native species for resources, disrupting the ecosystem', 'Always helps native species thrive', 'Has no interaction with native species', 'Immediately goes extinct upon arrival', 'a'),
  (1, true, 6, NULL, 'Which of these is a conservation strategy used to protect biodiversity?', 'Establishing protected wildlife sanctuaries and national parks', 'Unlimited hunting of endangered species', 'Clearing all forests for development', 'Ignoring pollution regulations', 'a'),
  (1, true, 6, NULL, 'Climate change threatens biodiversity mainly by', 'Altering habitats and weather patterns that species depend on', 'Having no effect on any ecosystem', 'Making every habitat more stable', 'Increasing biodiversity everywhere', 'a'),
  (1, true, 6, NULL, 'Which of these best describes a food web compared to a single food chain?', 'A food web is just one straight path of energy', 'A food web shows the interconnected feeding relationships among many organisms', 'A food web only includes producers', 'A food web has no decomposers', 'b'),
  (1, true, 6, NULL, 'Which of these best explains why decomposers are essential to nutrient cycling in an ecosystem?', 'They break down dead organisms, returning nutrients to the soil for producers to reuse', 'They compete directly with top predators for food', 'They convert sunlight into food energy', 'They have no role in the ecosystem', 'a'),
  (1, true, 6, NULL, 'Pollution, such as chemical runoff into rivers, threatens biodiversity mainly by', 'Contaminating habitats and harming the organisms living there', 'Improving water quality for all species', 'Having no measurable effect on ecosystems', 'Only affecting organisms on land', 'a'),
  (1, true, 6, 'Plate tectonics is the theory that Earth''s lithosphere is divided into several large plates that move slowly over the mantle. The Philippines lies along the Pacific Ring of Fire, where several plates meet, causing frequent earthquakes and volcanic eruptions.', 'Why does the Philippines experience frequent earthquakes and volcanic activity?', 'Because it is located near the equator', 'Because it lies along the Pacific Ring of Fire where tectonic plates meet', 'Because it is an archipelago with many islands', 'Because of its tropical climate', 'b'),
  (1, true, 6, NULL, 'When two tectonic plates move toward each other and collide, this is called a', 'Convergent boundary', 'Divergent boundary', 'Transform boundary', 'Static boundary', 'a'),
  (1, true, 6, NULL, 'When two tectonic plates move apart from each other, this is called a', 'Convergent boundary', 'Divergent boundary', 'Transform boundary', 'Static boundary', 'b'),
  (1, true, 6, NULL, 'When two tectonic plates slide past each other horizontally, this is called a', 'Convergent boundary', 'Divergent boundary', 'Transform boundary', 'Static boundary', 'c'),
  (1, true, 6, NULL, 'The point inside the Earth where an earthquake originates is called the', 'Epicenter', 'Focus', 'Fault line', 'Crater', 'b'),
  (1, true, 6, NULL, 'The point on the Earth''s surface directly above where an earthquake originates is called the', 'Focus', 'Epicenter', 'Magma chamber', 'Trench', 'b'),
  (1, true, 6, NULL, 'The Richter scale is used to measure', 'The temperature of lava', 'The magnitude, or strength, of an earthquake', 'The height of a volcano', 'The speed of tectonic plates', 'b'),
  (1, true, 6, NULL, 'A wide, gently sloping volcano formed by fluid lava flows is called a', 'Cinder cone volcano', 'Shield volcano', 'Composite volcano', 'Dormant volcano only', 'b'),
  (1, true, 6, NULL, 'A steep, cone-shaped volcano built from alternating layers of lava and ash is called a', 'Shield volcano', 'Cinder cone volcano', 'Composite (stratovolcano)', 'Flat volcano', 'c'),
  (1, true, 6, NULL, 'A small, steep volcano made mostly of loose volcanic fragments is called a', 'Shield volcano', 'Composite volcano', 'Cinder cone volcano', 'Caldera only', 'c'),
  (1, true, 6, NULL, 'The gradual breaking down of rocks into smaller pieces due to wind, water, or ice is called', 'Weathering', 'Erosion', 'Subduction', 'Sedimentation only', 'a'),
  (1, true, 6, NULL, 'The process of moving weathered rock and soil from one place to another, usually by water or wind, is called', 'Weathering', 'Erosion', 'Subduction', 'Crystallization', 'b'),
  (1, true, 6, NULL, 'Which of these best explains why the Philippines has both mountains and deep ocean trenches nearby?', 'The movement and collision of tectonic plates over millions of years shaped these features', 'The islands were built entirely by humans', 'The Philippines has no connection to tectonic activity', 'Mountains and trenches always form randomly with no cause', 'a'),
  (1, true, 6, NULL, 'Static electricity is best described as', 'An electric charge that builds up on a surface without flowing continuously', 'Electricity that always flows through a circuit', 'The same thing as current electricity', 'Electricity found only in lightning', 'a'),
  (1, true, 6, NULL, 'Current electricity is best described as', 'A continuous flow of electric charge through a conductor', 'A charge that never moves', 'Electricity that only exists in clouds', 'The same as magnetism', 'a'),
  (1, true, 6, NULL, 'In a series circuit, if one bulb burns out, what happens to the rest of the circuit?', 'The other bulbs stay lit as normal', 'The entire circuit is broken and all bulbs go out', 'The other bulbs get brighter', 'Nothing changes at all', 'b'),
  (1, true, 6, NULL, 'In a parallel circuit, if one bulb burns out, what happens to the rest of the circuit?', 'All bulbs go out', 'The other bulbs can still light up because they have separate paths', 'The circuit stops working entirely', 'The wires melt immediately', 'b'),
  (1, true, 6, NULL, 'Which of these materials would be the best conductor of electricity?', 'Copper wire', 'Rubber', 'Plastic', 'Wood', 'a'),
  (1, true, 6, NULL, 'Which of these materials would be the best insulator against electricity?', 'Copper', 'Aluminum', 'Rubber', 'Iron', 'c'),
  (1, true, 6, NULL, 'An electromagnet is created when', 'Electric current flows through a coiled wire, creating a magnetic field', 'A permanent magnet is heated', 'Two insulators are rubbed together', 'A circuit is completely disconnected', 'a'),
  (1, true, 6, NULL, 'Which of these is a practical use of electromagnets in everyday devices?', 'Electric motors and doorbells', 'Wooden furniture', 'Cotton clothing', 'Glass windows', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why electrical wires are often covered in rubber or plastic?', 'These materials insulate the wire, preventing electric shocks', 'These materials conduct electricity better than the metal wire', 'These materials make the wire heavier', 'These materials have no practical purpose', 'a'),
  (1, true, 6, NULL, 'Which of these best describes puberty?', 'A stage of growth and development when the body changes as a person matures from childhood toward adulthood', 'A disease that only some people experience', 'A stage that only affects a person''s height', 'Something that happens only in old age', 'a'),
  (1, true, 6, NULL, 'Which of these is a common physical change during puberty?', 'Growth spurts in height', 'Losing all baby teeth at once', 'Becoming shorter', 'No physical changes occur', 'a'),
  (1, true, 6, NULL, 'Which of these is a common emotional or social change many young people experience during puberty?', 'Mood changes and a growing sense of independence', 'No change in feelings at all', 'Becoming completely uninterested in friendships', 'Losing the ability to think', 'a'),
  (1, true, 6, NULL, 'Human development generally progresses through which of these general life stages, in order?', 'Infancy, childhood, adolescence, adulthood', 'Adulthood, infancy, adolescence, childhood', 'Adolescence, adulthood, infancy, childhood', 'Childhood, adulthood, infancy, adolescence', 'a'),
  (1, true, 6, NULL, 'Which of these best describes responsible decision-making during the changes of adolescence?', 'Thinking through choices, considering consequences, and seeking guidance from trusted adults', 'Making choices without ever thinking about consequences', 'Avoiding all decisions entirely', 'Ignoring advice from trusted adults', 'a'),
  (1, true, 6, 'Ancient Mesopotamia, located between the Tigris and Euphrates rivers, is often called the "Cradle of Civilization." Its people developed one of the earliest writing systems, called cuneiform, and built organized city-states.', 'Why is Mesopotamia often called the "Cradle of Civilization"?', 'It was one of the earliest places where organized cities and writing developed', 'It was the largest continent in the ancient world', 'It had no rivers or agriculture', 'It was located in modern-day Philippines', 'a'),
  (1, true, 6, NULL, 'The early writing system developed in ancient Mesopotamia is called', 'Hieroglyphics', 'Cuneiform', 'Calligraphy', 'Braille', 'b'),
  (1, true, 6, NULL, 'The ancient Indus Valley Civilization was known for its', 'Well-planned cities with advanced drainage systems', 'Complete lack of city planning', 'Location in modern-day Philippines', 'Absence of any written language', 'a'),
  (1, true, 6, NULL, 'During China''s Han Dynasty, which of these was a major contribution to world culture?', 'The expansion of the Silk Road trade routes', 'The invention of the printing press in Europe', 'The founding of ancient Rome', 'The building of the pyramids of Egypt', 'a'),
  (1, true, 6, NULL, 'Ancient Japan developed a unique culture influenced by its', 'Isolation as an island nation and its relationships with neighboring China and Korea', 'Complete isolation from all other civilizations at all times', 'Location in the Mediterranean Sea', 'Total lack of any trade or contact with others', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why studying ancient Asian civilizations like Mesopotamia and the Indus Valley is valuable?', 'They show the origins of early writing, government, and technology that influenced later societies', 'They have no connection to modern civilization', 'They only matter to people living in those regions today', 'They prove nothing important happened before modern history', 'a'),
  (1, true, 6, NULL, 'Which of these ancient civilizations developed along the Tigris and Euphrates rivers?', 'Indus Valley', 'Mesopotamia', 'Han China', 'Ancient Japan', 'b'),
  (1, true, 6, NULL, 'The American colonial period in the Philippines began in what year, after the Spanish-American War?', '1898', '1946', '1972', '1986', 'a'),
  (1, true, 6, NULL, 'The American teachers sent to the Philippines to help establish the public education system were called', 'Ilustrados', 'Thomasites', 'Katipuneros', 'Principalia', 'b'),
  (1, true, 6, NULL, 'The Philippine Commonwealth period was established to prepare the country for', 'Full independence from the United States', 'Permanent American rule', 'Japanese occupation', 'Spanish colonization again', 'a'),
  (1, true, 6, NULL, 'During World War II, the Philippines was occupied by which country?', 'Spain', 'Japan', 'Germany', 'China', 'b'),
  (1, true, 6, NULL, 'The Philippines gained full independence from the United States on', 'June 12, 1898', 'July 4, 1946', 'September 21, 1972', 'February 25, 1986', 'b'),
  (1, true, 6, NULL, 'Which of these best explains the significance of the Thomasites'' work in the Philippines?', 'They helped establish a widespread public education system using English as the medium of instruction', 'They led the Philippine Revolution against Spain', 'They were Filipino soldiers during World War II', 'They wrote the Philippine constitution', 'a'),
  (1, true, 6, NULL, 'Martial Law in the Philippines, declared by President Ferdinand Marcos, began in what year?', '1946', '1972', '1986', '1998', 'b'),
  (1, true, 6, NULL, 'The People Power Revolution, which ended the Marcos dictatorship, took place along which avenue?', 'Roxas Boulevard', 'EDSA (Epifanio de los Santos Avenue)', 'Ayala Avenue', 'Quezon Avenue', 'b'),
  (1, true, 6, NULL, 'In what year did the People Power Revolution (EDSA Revolution) take place?', '1972', '1986', '1946', '1998', 'b'),
  (1, true, 6, NULL, 'Which of these best describes the significance of the People Power Revolution?', 'It was a peaceful uprising that restored democracy after years of Martial Law', 'It was a violent war between two foreign countries', 'It led to the start of Martial Law', 'It had no lasting effect on Philippine history', 'a'),
  (1, true, 6, NULL, 'In economics, when demand for a product increases while supply stays the same, what usually happens to the price?', 'The price usually increases', 'The price usually decreases', 'The price always stays the same', 'Supply and demand have no effect on price', 'a'),
  (1, true, 6, NULL, 'In economics, when the supply of a product increases while demand stays the same, what usually happens to the price?', 'The price usually increases', 'The price usually decreases', 'The price always doubles', 'Supply has no effect on price', 'b'),
  (1, true, 6, NULL, 'Money collected by the government from citizens and businesses to fund public services is called', 'Taxation', 'Inflation', 'Investment', 'Barter', 'a'),
  (1, true, 6, NULL, 'A government budget is best described as', 'A plan for how the government will spend and collect money over a period of time', 'A type of tax only', 'A private company''s savings account', 'An agreement between two countries', 'a'),
  (1, true, 6, NULL, 'Which of these is an example of an economic institution that helps people save and borrow money?', 'A bank', 'A school', 'A barangay hall', 'A hospital', 'a'),
  (1, true, 6, NULL, 'A cooperative is an organization where members', 'Work together and pool resources for mutual economic benefit', 'Compete against each other with no cooperation', 'Are required to pay only the government', 'Have no shared goals at all', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why governments collect taxes?', 'To fund public services like schools, roads, and healthcare', 'To make citizens poorer with no benefit', 'Taxes serve no real purpose', 'To only benefit government officials personally', 'a'),
  (1, true, 6, NULL, 'The branch of Philippine government responsible for making laws is the', 'Executive branch', 'Legislative branch', 'Judicial branch', 'Local branch only', 'b'),
  (1, true, 6, NULL, 'The branch of Philippine government responsible for enforcing and implementing laws is the', 'Legislative branch', 'Judicial branch', 'Executive branch', 'None of these', 'c'),
  (1, true, 6, NULL, 'The branch of Philippine government responsible for interpreting laws and settling legal disputes is the', 'Executive branch', 'Legislative branch', 'Judicial branch', 'Local branch only', 'c'),
  (1, true, 6, NULL, 'LGU stands for', 'Local Government Unit', 'Legal Government Union', 'Limited Government Utility', 'Land Governance Unit', 'a'),
  (1, true, 6, NULL, 'Which of these is the correct first step in the process of a bill becoming a law in the Philippines?', 'The bill is signed by the President immediately', 'The bill is filed and introduced in Congress', 'The bill skips Congress entirely', 'The bill is only discussed by ordinary citizens', 'b'),
  (1, true, 6, NULL, 'After a bill is passed by both houses of Congress, what typically happens next?', 'It goes to the President to be signed into law or vetoed', 'It is automatically discarded', 'It becomes law without any further steps', 'It returns to the barangay for approval', 'a'),
  (1, true, 6, NULL, 'The United Nations (UN) was established mainly to', 'Promote international peace, security, and cooperation among countries', 'Start conflicts between nations', 'Replace all national governments', 'Focus only on trade agreements', 'a'),
  (1, true, 6, NULL, 'The World Health Organization (WHO) focuses mainly on', 'Global public health issues and disease prevention', 'International trade agreements', 'Military alliances', 'Currency exchange rates', 'a'),
  (1, true, 6, NULL, 'UNICEF is an international organization that focuses mainly on', 'The welfare and rights of children around the world', 'Military defense', 'Space exploration', 'Currency regulation', 'a'),
  (1, true, 6, NULL, 'The World Trade Organization (WTO) mainly deals with', 'Rules and agreements for international trade between countries', 'Global healthcare policy', 'Children''s rights', 'Space exploration', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why the Philippines participates in international organizations like the UN and ASEAN?', 'To cooperate with other nations on shared global and regional issues', 'To isolate itself from world affairs', 'These organizations have no relevance to the Philippines', 'To avoid any international relationships', 'a'),
  (1, true, 6, NULL, 'In literature, the central message or underlying idea of a story is called its', 'Theme', 'Setting', 'Plot', 'Genre', 'a'),
  (1, true, 6, NULL, 'An object, person, or place that represents a deeper meaning beyond its literal sense is called a', 'Symbol', 'Setting', 'Narrator', 'Dialogue', 'a'),
  (1, true, 6, NULL, 'A recurring idea or image that appears throughout a literary work is called a', 'Motif', 'Climax', 'Exposition', 'Resolution only', 'a'),
  (1, true, 6, NULL, 'When the outcome of a situation is the opposite of what was expected, this is an example of', 'Foreshadowing', 'Irony', 'Alliteration', 'Rhyme', 'b'),
  (1, true, 6, NULL, 'A story where characters and events represent broader ideas or moral lessons, like a political or religious message, is called an', 'Allegory', 'Autobiography', 'Glossary', 'Index', 'a'),
  (1, true, 6, NULL, 'The perspective from which a story is told, such as first-person or third-person, is called', 'Point of view', 'Setting', 'Theme', 'Dialogue', 'a'),
  (1, true, 6, NULL, 'A story told using "I" and "we," from a character directly involved in the events, uses which point of view?', 'First-person', 'Third-person omniscient', 'Second-person', 'Objective only', 'a'),
  (1, true, 6, NULL, 'A narrator who knows the thoughts and feelings of all characters in a story uses which point of view?', 'First-person', 'Third-person omniscient', 'Second-person', 'Limited to one character only, with no other perspective', 'b'),
  (1, true, 6, NULL, 'A technique authors use to build suspense by hinting at events that will happen later is called', 'Foreshadowing', 'Flashback', 'Denouement', 'Epilogue only', 'a'),
  (1, true, 6, NULL, 'A scene that interrupts the current story to show an earlier event is called a', 'Foreshadowing', 'Flashback', 'Climax', 'Resolution', 'b'),
  (1, true, 6, NULL, 'In an argumentative essay, the main position or statement the writer is trying to prove is called the', 'Claim', 'Rebuttal', 'Counterargument', 'Citation', 'a'),
  (1, true, 6, NULL, 'In an argumentative essay, facts, examples, or data used to support the claim are called', 'Evidence', 'Rebuttal', 'Bias', 'Plagiarism', 'a'),
  (1, true, 6, NULL, 'In an argumentative essay, the explanation connecting the evidence to the claim is called the', 'Warrant', 'Counterargument', 'Bibliography', 'Footnote', 'a'),
  (1, true, 6, NULL, 'In an argumentative essay, an opposing viewpoint that the writer acknowledges is called a', 'Counterargument', 'Warrant', 'Claim', 'Citation', 'a'),
  (1, true, 6, NULL, 'In an argumentative essay, the writer''s response that addresses and weakens the counterargument is called the', 'Rebuttal', 'Claim', 'Warrant', 'Bibliography', 'a'),
  (1, true, 6, NULL, 'A source written by someone who directly experienced or witnessed an event, like a diary or original document, is called a', 'Primary source', 'Secondary source', 'Unreliable source', 'Fictional source', 'a'),
  (1, true, 6, NULL, 'A source that analyzes or interprets information from primary sources, like a textbook or documentary, is called a', 'Primary source', 'Secondary source', 'An unreliable source only', 'A fictional source only', 'b'),
  (1, true, 6, NULL, 'Which of these is a sign that a source might be unreliable?', 'It has no author, no evidence, and makes claims that cannot be verified', 'It is written by an expert with cited evidence', 'It is peer-reviewed by other scholars', 'It provides clear references to its data', 'a'),
  (1, true, 6, NULL, 'Using someone else''s words or ideas without giving them credit is called', 'Citation', 'Plagiarism', 'Paraphrasing correctly', 'Research', 'b'),
  (1, true, 6, NULL, 'Which of these correctly shows how to avoid plagiarism when using another person''s idea?', 'Citing the original source and giving proper credit', 'Copying the text exactly without any credit', 'Claiming the idea as your own original thought', 'Ignoring the need to reference sources', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses a Type 1 conditional (real, possible future situation)?', 'If it rains tomorrow, we will stay indoors.', 'If it rained, we would stay indoors.', 'If it had rained, we would have stayed indoors.', 'If it rains, we stayed indoors.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses a Type 2 conditional (hypothetical, unlikely present situation)?', 'If I win the lottery, I will buy a house.', 'If I won the lottery, I would buy a house.', 'If I had won the lottery, I would have bought a house.', 'If I win the lottery, I bought a house.', 'b'),
  (1, true, 6, NULL, 'Which sentence correctly uses a Type 3 conditional (impossible past situation)?', 'If I had studied harder, I would have passed the test.', 'If I study harder, I will pass the test.', 'If I studied harder, I would pass the test.', 'If I study harder, I passed the test.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses reported speech to report what someone said?', 'She said, "I am tired."', 'She said that she was tired.', 'She said that I am tired.', 'She said tired I am.', 'b'),
  (1, true, 6, NULL, 'Which sentence correctly uses a relative clause to add information about a noun?', 'The book, which I borrowed from the library, was fascinating.', 'The book which, I borrowed, from the library was fascinating.', 'The book I borrowed which from the library was fascinating.', 'The book was, which I borrowed, fascinating from the library.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses a gerund (verb + -ing acting as a noun)?', 'Swimming is her favorite hobby.', 'She swims her favorite hobby.', 'She to swim her favorite hobby.', 'Swim is her favorite hobby, ing.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses an infinitive (to + base verb)?', 'She wants to travel the world.', 'She wants traveling the world to.', 'She want to travels the world.', 'She wants travel to the world.', 'a'),
  (1, true, 6, NULL, 'Which pair of words are near-synonyms with a subtle difference in nuance: "frugal" and "stingy"?', 'Frugal suggests wise spending, while stingy suggests an unwillingness to spend even when appropriate', 'They mean exactly the same thing with no difference', 'Frugal means wasteful, and stingy means generous', 'They are complete opposites with no similarity', 'a'),
  (1, true, 6, NULL, 'The idiomatic expression "break the ice" means to', 'Literally break a piece of ice', 'Start a conversation or ease tension in a social situation', 'End a friendship', 'Cause an argument', 'b'),
  (1, true, 6, NULL, 'The idiomatic expression "hit the books" means to', 'Physically hit a book', 'Study seriously', 'Throw books away', 'Stop reading', 'b'),
  (1, true, 6, NULL, 'Which of these best explains why writers choose advanced academic vocabulary over simpler synonyms in formal writing?', 'Precise, formal vocabulary can convey more exact meaning appropriate to an academic or professional context', 'Advanced vocabulary always confuses readers with no benefit', 'Simple words are always incorrect in any context', 'Word choice never affects tone or meaning', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why an author might use symbolism instead of stating an idea directly?', 'It adds depth and allows readers to interpret deeper meaning through imagery', 'It always confuses the reader with no purpose', 'Symbolism is never used in serious literature', 'It replaces the need for a plot', 'a'),
  (1, true, 6, NULL, 'Ang dulang binubuo lamang ng isang yugto o eksena ay tinatawag na', 'Full-length na dula', 'Isang yugtong dula (one-act play)', 'Epiko', 'Tula', 'b'),
  (1, true, 6, NULL, 'Sa isang dula, ang mga salitang binibigkas ng mga tauhan sa isa''t isa ay tinatawag na', 'Diyalogo', 'Tagpuan', 'Banghay', 'Direksyon sa entablado only', 'a'),
  (1, true, 6, NULL, 'Ang tagubilin sa dula na naglalarawan ng galaw, ekspresyon, o kilos ng tauhan ay tinatawag na', 'Diyalogo', 'Direksyon sa entablado (stage direction)', 'Tayutay', 'Tagpuan', 'b'),
  (1, true, 6, NULL, 'Sa isang dula, ang lugar at panahon ng pangyayari ay tinatawag na', 'Tagpuan', 'Diyalogo', 'Tauhan', 'Banghay lamang', 'a'),
  (1, true, 6, NULL, 'Ang tayutay na ginagamit sa isang dula ay nakakatulong upang', 'Magpahayag ng damdamin at bigyang-diin ang mensahe', 'Palitan ang tauhan', 'Alisin ang banghay', 'Walang epekto sa dula', 'a'),
  (1, true, 6, NULL, 'Ang talambuhay ay isang uri ng panitikan na', 'Isinusulat ng ibang tao tungkol sa buhay ng isang tunay na tao', 'Isinusulat ng tao mismo tungkol sa sariling buhay', 'Isang kathang-isip na kwento', 'Isang uri ng bugtong', 'a'),
  (1, true, 6, NULL, 'Ang awtobiyograpiya ay isang uri ng panitikan na', 'Isinusulat ng ibang tao tungkol sa iba', 'Isinusulat ng tao mismo tungkol sa sariling buhay', 'Isang kwentong bayan', 'Isang uri ng salawikain', 'b'),
  (1, true, 6, NULL, 'Ang pangunahing layunin ng talambuhay o awtobiyograpiya ay', 'Ibahagi ang mahahalagang karanasan at kontribusyon ng isang tao', 'Magbigay ng katha-katha na kwento lamang', 'Magturo ng matematika', 'Walang tunay na layunin', 'a'),
  (1, true, 6, NULL, 'Sa pagtataya ng nilalaman ng isang talambuhay, mahalagang alamin ang', 'Katotohanan at kredibilidad ng mga impormasyong isinulat', 'Kulay ng aklat lamang', 'Bilang ng pahina lamang', 'Pangalan ng publisher lamang', 'a'),
  (1, true, 6, NULL, 'Ang pahayag na nagsisimula sa pangkalahatang ideya patungo sa tiyak na konklusyon ay tinatawag na', 'Deduktibong pangangatwiran', 'Induktibong pangangatwiran', 'Bias', 'Tayutay', 'a'),
  (1, true, 6, NULL, 'Ang pahayag na nagsisimula sa tiyak na obserbasyon patungo sa pangkalahatang konklusyon ay tinatawag na', 'Deduktibong pangangatwiran', 'Induktibong pangangatwiran', 'Plagiarism', 'Onomatopeya', 'b'),
